<?php
declare(strict_types=1);
require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/research-entities.php';
$u=require_user($pdo);$id=(string)($_GET['id']??$_POST['id']??'');$entity=research_entity_access($pdo,$u,$id);if(!$entity){http_response_code(404);exit('Research entity not found.');}$canWrite=project_can_write($entity);$success='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$op=(string)($_POST['op']??'');try{
    if(!$canWrite)throw new RuntimeException('You have view-only access to this project.');
    if($op==='update'){$status=(string)($_POST['status']??'confirmed');if(!in_array($status,['suggested','confirmed','archived'],true))$status='confirmed';$pdo->prepare('UPDATE research_entities SET status=?,description=?,updated_at=NOW() WHERE id=?')->execute([$status,trim((string)($_POST['description']??''))?:null,$entity['id']]);$success='Entity updated.';}
