    if($op==='remove_mention'){$pdo->prepare('DELETE FROM research_entity_mentions WHERE public_id=? AND entity_id=? AND project_id=?')->execute([(string)($_POST['mention']??''),$entity['id'],$entity['project_id']]);$success='Reference removed.';}
}catch(Throwable $e){$error=$e->getMessage();}$entity=research_entity_access($pdo,$u,$id)??$entity;}
$mentions=research_entity_mentions($pdo,(int)$entity['project_id'],(int)$entity['id']);$relations=research_entity_relation_rows($pdo,(int)$entity['project_id'],(int)$entity['id']);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($entity['canonical_name'])?> · Entity · Annotated</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/home.php">Annotated</a><nav><a href="/research-entities.php?id=<?=h($entity['project_public_id'])?>">Entity Graph</a><a href="/research-knowledge.php?id=<?=h($entity['project_public_id'])?>">Knowledge</a><a href="/research.php">Research</a></nav></header><main class="layout"><section><div class="pageTitle"><span class="eyebrow">ENTITY · <?=h(strtoupper($entity['entity_type']))?> · <?=h(strtoupper($entity['status']))?></span><h1><?=h($entity['canonical_name'])?></h1><?php if($entity['description']):?><p><?=nl2br(h($entity['description']))?></p><?php endif?><p class="meta">Created via <?=h($entity['source_type'])?><?php if($entity['ai_run_public_id']):?> · AI run <?=h($entity['ai_run_public_id'])?><?php endif?></p></div><?php if($success):?><div class="success"><?=h($success)?></div><?php endif?><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?>
